package com.example.starter.domain;

/**
 * 列车作业状态: RECEIVED=作业中, DEPARTURE_CONFIRMED=已发车确认, CLOSED=已销记(终态)。
 */
public enum OperationStatus {
    RECEIVED,
    DEPARTURE_CONFIRMED,
    CLOSED
}

package com.example.starter.domain;

/**
 * 制动试验项: SENSITIVITY=感度试验(减压50kPa), STABILITY=安定试验(减压140kPa)。
 */
public enum TestPhase {
    SENSITIVITY,
    STABILITY
}

package com.example.starter.domain;

/**
 * 制动试验结论: PASS=合格, FAIL=不合格。
 */
public enum TestResult {
    PASS,
    FAIL
}

package com.example.starter.domain;

import com.example.starter.domain.OperationStatus;

/**
 * 列车作业行(对应 train_operation 表)。
 *
 * @param id               作业主键
 * @param trackNo          股道号
 * @param trainNo          车次
 * @param setPressureKpa   制动管定压(kPa)
 * @param status           作业状态
 * @param consistVersion   当前编组版本号
 * @param recoveryPending  感度合格后是否等待风压恢复定压
 * @param recoveryOk       风压是否已恢复至定压(恰达定压为恢复)
 */
public record OperationRow(long id, String trackNo, String trainNo, int setPressureKpa,
                           OperationStatus status, int consistVersion,
                           boolean recoveryPending, boolean recoveryOk) {
}

package com.example.starter.domain;

import java.math.BigDecimal;

/**
 * 编组车辆行(对应 operation_car 表), 每个编组版本保存完整快照。
 *
 * @param id             车辆行主键
 * @param operationId    所属作业ID
 * @param consistVersion 所属编组版本号
 * @param carNo          车辆号(合成数据)
 * @param lengthCoeff    换长
 * @param weightTons     总重(吨)
 * @param brakeCutout    是否关门车
 */
public record CarRow(long id, long operationId, int consistVersion, String carNo,
                     BigDecimal lengthCoeff, BigDecimal weightTons, boolean brakeCutout) {
}

package com.example.starter.domain;

import java.math.BigDecimal;

/**
 * 编组核对记录行(对应 consist_check 表)。
 */
public record ConsistCheckRow(long id, long operationId, int consistVersion,
                              int expectedCars, BigDecimal expectedLength, BigDecimal expectedWeight,
                              int actualCars, BigDecimal actualLength, BigDecimal actualWeight,
                              boolean matched) {
}

package com.example.starter.domain;

import java.time.LocalDateTime;

/**
 * 制动试验记录行(对应 brake_test 表)。
 */
public record BrakeTestRow(long id, long operationId, int consistVersion, TestPhase phase,
                           int reductionKpa, Boolean allCarsBraked, Boolean emergencyOccurred,
                           TestResult result, boolean valid, LocalDateTime createdAt) {
}

package com.example.starter.domain;

import java.time.LocalDateTime;

/**
 * 风压读数行(对应 pressure_reading 表)。
 */
public record PressureReadingRow(long id, long operationId, int pressureKpa,
                                 LocalDateTime occurredAt, boolean late, LocalDateTime createdAt) {
}

package com.example.starter.domain;

/**
 * 幂等受理记录行(对应 idempotency_record 表)。
 *
 * @param requestId      幂等键
 * @param endpoint       受理的业务端点
 * @param fingerprint    请求指纹(端点+requestId+全部业务字段的SHA-256)
 * @param responseStatus 首次受理的HTTP状态码, NULL 表示处理中
 * @param responseBody   首次受理的响应体JSON, NULL 表示处理中
 */
public record IdempotencyRow(String requestId, String endpoint, String fingerprint,
                             Integer responseStatus, String responseBody) {
}

