package com.example.starter.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 车辆输入(合成数据)。
 *
 * @param carNo       车辆号
 * @param lengthCoeff 换长
 * @param weightTons  总重(吨)
 * @param brakeCutout 是否关门车
 */
public record CarInput(
        @NotBlank String carNo,
        @NotNull @DecimalMin("0.01") BigDecimal lengthCoeff,
        @NotNull @DecimalMin("0.01") BigDecimal weightTons,
        boolean brakeCutout) {
}

package com.example.starter.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

import java.util.List;

/**
 * 接入请求: 建立列车作业并登记初始编组。
 *
 * @param requestId       幂等键
 * @param trackNo         股道号(同股道同时刻只允许一列作业中列车)
 * @param trainNo         车次
 * @param setPressureKpa  制动管定压(kPa)
 * @param cars            初始编组车辆清单
 */
public record ReceiveRequest(
        @NotBlank String requestId,
        @NotBlank String trackNo,
        @NotBlank String trainNo,
        @Min(1) int setPressureKpa,
        @NotEmpty List<@Valid CarInput> cars) {
}

package com.example.starter.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;

import java.util.List;

/**
 * 摘挂请求: 在同一事务内变更编组并作废原试验结论。
 *
 * @param requestId    幂等键
 * @param attachCars   挂车清单(可为空)
 * @param detachCarNos 摘车车辆号清单(可为空)
 */
public record ShuntRequest(
        @NotBlank String requestId,
        List<@Valid CarInput> attachCars,
        List<String> detachCarNos) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;

/**
 * 编组核对请求: 与合成运统1 核对辆数/换长/总重。
 */
public record ConsistCheckRequest(
        @NotBlank String requestId,
        @Min(1) int expectedCars,
        @NotNull BigDecimal expectedLength,
        @NotNull BigDecimal expectedWeight) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;

import java.time.LocalDateTime;

/**
 * 风压上报请求。
 *
 * @param requestId   幂等键
 * @param pressureKpa 制动管风压(kPa)
 * @param occurredAt  采集时间(本地时区); 为空时取服务器当前时间
 */
public record PressureRequest(
        @NotBlank String requestId,
        @Min(0) int pressureKpa,
        LocalDateTime occurredAt) {
}

package com.example.starter.dto;

import com.example.starter.domain.TestPhase;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 制动试验请求。
 *
 * @param requestId         幂等键
 * @param phase             试验项: SENSITIVITY=感度, STABILITY=安定
 * @param reductionKpa      减压量(kPa): 感度恰50合格, 安定恰140合格
 * @param allCarsBraked     感度试验必填: 全列是否制动
 * @param emergencyOccurred 安定试验必填: 是否发生紧急制动
 */
public record BrakeTestRequest(
        @NotBlank String requestId,
        @NotNull TestPhase phase,
        @Min(0) int reductionKpa,
        Boolean allCarsBraked,
        Boolean emergencyOccurred) {
}

package com.example.starter.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 仅含幂等键的请求(发车确认/销记)。
 */
public record RequestIdRequest(@NotBlank String requestId) {
}

