package com.example.starter.dto;

/**
 * 接入响应。
 */
public record ReceiveResponse(long operationId, String status, int consistVersion, int carCount) {
}

package com.example.starter.dto;

import java.math.BigDecimal;

/**
 * 摘挂响应: 返回新编组版本及重新汇总的辆数/换长/总重。
 */
public record ShuntResponse(long operationId, int consistVersion, int carCount,
                            BigDecimal totalLength, BigDecimal totalWeight) {
}

package com.example.starter.dto;

import java.math.BigDecimal;

/**
 * 编组核对响应: matched=false 时发车确认将被拒绝。
 */
public record ConsistCheckResponse(long operationId, int consistVersion, boolean matched,
                                   int expectedCars, BigDecimal expectedLength, BigDecimal expectedWeight,
                                   int actualCars, BigDecimal actualLength, BigDecimal actualWeight) {
}

package com.example.starter.dto;

/**
 * 风压上报响应: late=true 表示销记后迟到数据, 仅记迟到事件。
 */
public record PressureResponse(long operationId, boolean recorded, boolean late) {
}

package com.example.starter.dto;

import com.example.starter.domain.TestPhase;
import com.example.starter.domain.TestResult;

/**
 * 制动试验响应。
 */
public record BrakeTestResponse(long operationId, int consistVersion, TestPhase phase,
                                int reductionKpa, TestResult result) {
}

package com.example.starter.dto;

import java.util.List;

/**
 * 发车确认响应: confirmed=false 时 reasons 给出拒绝原因(HTTP 422)。
 */
